; b04_nack_error -- a transfer nobody acknowledges sets the Peri error latch
; Layer-2 conformance test (generated by conformance/make_conformance.py: edit that, not this file).
; Checks: NACK -> the sticky error latch; BR.IF_ERROR / IF_NO_ERROR; the sequencer goes on after a NACK
; Results go to the result CSRs RES + n (conf_defs.inc); the last write is RES_DONE = 0xA5. Expected values: b04_nack_error.expected.csv
.include "conf_defs.inc"
.devmap 0, I2C, 0x2D, DEV_ABSENT          ; NO device answers at this address on the bench
.peri
    BR.IF_NO_ERROR clean                       ; before any transfer the latch is clear
    EXEC_CSR WRITE8 RES + 0, 0xE0
    JMP go
clean:
    EXEC_CSR WRITE8 RES + 0, 0x0C
go:
    EXEC_XFER READ dev=DEV_ABSENT, addr=0x00, addrlen=1, ptr=0
    BR.IF_ERROR failed
    EXEC_CSR WRITE8 RES + 1, 0x0E
    JMP after
failed:
    EXEC_CSR WRITE8 RES + 1, 0xE1
after:
    BR.IF_ERROR still                          ; the latch stays set (nothing cleared it)
    EXEC_CSR WRITE8 RES + 2, 0x02
    JMP fin
still:
    EXEC_CSR WRITE8 RES + 2, 0xE2
fin:
    EXEC_CSR WRITE8 RES_DONE, 0xA5          ; the last write: everything above is there
pdone:
    JMP pdone
